matching_patterns = []
for bits in range(1 << 9):
    grid = []
    for i in range(3):
        row = []
        for j in range(3):
            idx = i*3 + j
            if (bits >> idx) & 1:
                row.append(6)
            else:
                row.append(4)
        grid.append(row)
    if grid == demo1_output:
        matching_patterns.append(bits)  # Should be exactly one!
        break

print(f"Unique pattern matching Demo 1: {matching_patterns}")

# Convert bits to a visual string
def bits_to_grid(bits):
    grid = []
    for i in range(3):
        row = []
        for j in range(3):
            idx = i*3 + j
            if (bits >> idx) & 1:
                row.append('P')
            else:
                row.append('B')
        grid.append(row)
    return grid

